-- ================================================================================================
-- Sierra de la Pila · N2 completo: espacio, hábitats, especies y vínculos.
--
-- GENERADO por Tools/catalogo-nacional/build-park-sql.js desde Frontend\Data\parks\murcia\sierra-de-la-pila\park.json
-- y Data/parks/murcia/sierra-de-la-pila/geo/habitats.geojson. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-park-sql.js --park sierra-de-la-pila
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado:
-- con backend desplegado, un espacio que no esté en la base de datos no existe para el usuario.
--
-- Contenido: 1 espacio · 10 hábitats · 219 especies · 689 vínculos especie↔hábitat.
-- Los puntos de interés van aparte, en `n3-pois-<slug>.sql` (build-poi-sql.js).
--
-- ORDEN: la fila de `parks` va PRIMERO y no es opcional. Sin ella los INSERT ... SELECT de
-- abajo no encuentran nada y cargan CERO filas sin dar ningún error.
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre las claves únicas del esquema. Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database\sierra-de-la-pila-n2.sql
-- ================================================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------------------------------------
-- 1. El espacio. Sin esta fila, TODO lo demás carga cero filas en silencio.
-- ------------------------------------------------------------------------------------------------
INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('sierra-de-la-pila', 'Sierra de la Pila', 'Parque Regional', 'Región de Murcia', 'Murcia', 'Abarán y Blanca y Fortuna y Jumilla y Molina de Segura', 'Una isla de bosque sobre el valle del Segura: pinares y carrascales hasta cerca de los 1.300 m, con fuentes, cortados y rapaces sobre el llano árido.', 38.26383, -1.23433, 'available')
ON DUPLICATE KEY UPDATE
    name = VALUES(name), category = VALUES(category), region = VALUES(region),
    province = VALUES(province), municipality = VALUES(municipality),
    description = VALUES(description), latitude = VALUES(latitude),
    longitude = VALUES(longitude), status = VALUES(status);

-- ------------------------------------------------------------------------------------------------
-- 2. Hábitats (10). `geometry` sale del geojson; sin ella el mapa dibuja un círculo.
