    SELECT 'prados-calcareos-carsticos-6110', '6110', 'Prados calcáreos cársticos o basófilos del Alysso-Sedion albi', 'Pastos', 'Pastos abiertos sobre repisas y lanchas de roca caliza con apenas un dedo de tierra encima. Ahí solo prosperan plantas crasas de hojas gordas, como las uñas de gato (Sedum), y hierbas anuales minúsculas que nacen, florecen y mueren entre febrero y mayo. Ocupa superficies muy pequeñas y depende de que el suelo siga siendo escaso: en cuanto se acumula tierra, otras plantas lo desplazan.', 1, 38.277075, -1.220867, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.248527,38.24615],[-1.248436,38.245432],[-1.248328,38.244962],[-1.248268,38.244312],[-1.248005,38.243632],[-1.247432,38.242858],[-1.246495,38.242366],[-1.24588,38.24196],[-1.245387,38.241345],[-1.244851,38.240431],[-1.244416,38.239803],[-1.243979,38.239138],[-1.242943,38.238078],[-1.242383,38.237884],[-1.241962,38.23791],[-1.24125,38.238228],[-1.240898,38.238452],[-1.240415,38.239017],[-1.240242,38.240317],[-1.240177,38.24142],[-1.240877,38.24244],[-1.241932,38.243271],[-1.242598,38.243871],[-1.243003,38.244157],[-1.243322,38.244459],[-1.243762,38.244884],[-1.244122,38.245124],[-1.244657,38.245385],[-1.245105,38.245657],[-1.24583,38.245947],[-1.24661,38.246477],[-1.247137,38.246886],[-1.248039,38.246917],[-1.248402,38.246612],[-1.248527,38.24615]]],[[[-1.240403,38.276307],[-1.23997,38.276052],[-1.239562,38.276033],[-1.239266,38.275925],[-1.238681,38.275848],[-1.23726,38.275913],[-1.234582,38.276764],[-1.23014,38.277833],[-1.227102,38.278134],[-1.225207,38.278646],[-1.224437,38.279283],[-1.224316,38.27984],[-1.224583,38.280254],[-1.225151,38.281069],[-1.225367,38.281172],[-1.225571,38.281242],[-1.225716,38.281321],[-1.22592,38.281414],[-1.226109,38.281471],[-1.226269,38.281528],[-1.226488,38.28163],[-1.226604,38.281641],[-1.22672,38.281688],[-1.226924,38.281767],[-1.227041,38.281801],[-1.22723,38.281867],[-1.227477,38.28196],[-1.227724,38.28205],[-1.227957,38.28213],[-1.228161,3