    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 38.266115, -1.27891, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.326884,38.250019],[-1.32684,38.249906],[-1.326796,38.249815],[-1.326796,38.249689],[-1.326694,38.249611],[-1.326563,38.249542],[-1.326432,38.249486],[-1.326257,38.249429],[-1.326097,38.249346],[-1.325908,38.24928],[-1.325733,38.249224],[-1.325573,38.249167],[-1.325457,38.24912],[-1.325282,38.249064],[-1.325122,38.249017],[-1.324948,38.248937],[-1.324773,38.248836],[-1.324671,38.248731],[-1.324612,38.248653],[-1.324366,38.248603],[-1.323141,38.249459],[-1.323084,38.249006],[-1.324559,38.248197],[-1.324611,38.248126],[-1.324713,38.248078],[-1.324887,38.248022],[-1.325033,38.247965],[-1.325039,38.247963],[-1.325493,38.247745],[-1.326034,38.247126],[-1.326034,38.247033],[-1.326006,38.246976],[-1.325777,38.246807],[-1.324969,38.247326],[-1.32376,38.246617],[-1.324288,38.246325],[-1.324288,38.246216],[-1.324287,38.246112],[-1.324287,38.246093],[-1.323408,38.245621],[-1.322645,38.24524],[-1.323777,38.245461],[-1.324362,38.245885],[-1.324417,38.245789],[-1.324519,38.245665],[-1.324591,38.245548],[-1.324678,38.245433],[-1.32478,38.245272],[-1.324881,38.245125],[-1.324968,38.245009],[-1.325055,38.244884],[-1.325128,38.244768],[-1.325186,38.244678],[-1.325229,38.244584],[-1.325233,38.244578],[-1.323971,38.2425],[-1.323969,38.242113],[-1.323005,38.240239],[-1.319648,38.23991],[-1.319363,38.24017],[-1.31901,38.240089],[-1.318895,38.240146],[-1.318764,38.240202],[-1.318604