    SELECT 'vegetacion-gipsicola-iberica-1520', '1520', 'Vegetación gipsícola ibérica (Gypsophiletalia)', 'Matorral', 'Matorral bajo y ralo que crece únicamente sobre yeso, un suelo blanquecino que forma costra y en el que casi ninguna otra planta prospera. Las que lo consiguen están especializadas en ese sustrato y muchas no viven en ningún otro sitio, de modo que cada afloramiento de yeso tiene su propia flora. No se recupera: al roturar o extraer el yeso desaparecen a la vez el suelo y lo que crecía sobre él.', 1, 38.241518, -1.259049, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.303246,38.248959],[-1.303107,38.248921],[-1.302947,38.248901],[-1.302787,38.248867],[-1.302627,38.248833],[-1.302481,38.248799],[-1.302321,38.248765],[-1.302132,38.248718],[-1.301943,38.248683],[-1.301783,38.248649],[-1.301536,38.248605],[-1.301347,38.248571],[-1.301157,38.248537],[-1.300954,38.248502],[-1.300751,38.248459],[-1.300532,38.248415],[-1.3003,38.24838],[-1.300081,38.248336],[-1.299849,38.248302],[-1.29963,38.248267],[-1.299398,38.248223],[-1.29918,38.248175],[-1.298976,38.248145],[-1.298786,38.248097],[-1.298583,38.248053],[-1.298379,38.248005],[-1.298161,38.247962],[-1.297943,38.247918],[-1.297667,38.247869],[-1.297521,38.247813],[-1.297332,38.247778],[-1.297128,38.247744],[-1.296939,38.247701],[-1.296765,38.247653],[-1.29659,38.247619],[-1.296401,38.247589],[-1.296212,38.247555],[-1.295994,38.247507],[-1.295747,38.247463],[-1.2955,38.247427],[-1.295237,38.247397],[-1.294903,38.247374],[-1.294699,38.247375],[-1.294423,38.247376],[-1.292896,38.247376],[-1.292591,38.247381],[-1.292286,38.24739],[-1.291995,38.247412],[-1.291704,38.247413],[-1.291413,38.247418],[-1.29086,38.247418],[-1.29057,38.247419],[-1.290308,38.247419],[-1.290061,38.24742],[-1.2898,38.247453],[-1.289683,38.247455],[-1.289613,38.247454],[-1.289494,38.247453],[-1.28913,38.247456],[-1.288898,38.247457],[-1.288593,38.247458],[-1.28801,38.247458],[-1.28772,38.247436],[-1.287429,38.247436],[-1.287138,3