    SELECT 'encinares-de-quercus-9340', '9340', 'Encinares de Quercus ilex y Quercus rotundifolia', 'Bosque', 'El bosque mediterráneo por excelencia: encinares y carrascales de hoja dura, pequeña y perenne, que aguantan tanto el calor del verano como las heladas del interior. Bajo los árboles crece un sotobosque denso de coscoja, lentisco, madroño, enebros y aromáticas, y en el suelo la bellota sostiene en otoño a jabalíes, palomas y arrendajos. Aclarado por el ser humano durante siglos, ha dado lugar a las dehesas.', 0, 38.262683, -1.247135, '#6b8e23', '{"type":"MultiPolygon","coordinates":[[[[-1.303154,38.24944],[-1.302594,38.24958],[-1.302321,38.249644],[-1.301695,38.249937],[-1.300678,38.250251],[-1.299957,38.250376],[-1.299109,38.25026],[-1.29826,38.250103],[-1.297009,38.250387],[-1.295063,38.251039],[-1.293167,38.251183],[-1.291628,38.251201],[-1.290634,38.25106],[-1.289615,38.251027],[-1.288278,38.251328],[-1.286778,38.251247],[-1.285102,38.251142],[-1.284034,38.251297],[-1.283132,38.251564],[-1.282349,38.251931],[-1.281407,38.252286],[-1.280652,38.252284],[-1.279729,38.252428],[-1.278673,38.252228],[-1.277974,38.25188],[-1.277104,38.252223],[-1.276383,38.252645],[-1.275445,38.252798],[-1.274604,38.252822],[-1.273888,38.252726],[-1.273221,38.252765],[-1.272465,38.253074],[-1.271366,38.253504],[-1.270004,38.253565],[-1.268002,38.25331],[-1.267127,38.252937],[-1.266571,38.252847],[-1.265598,38.252531],[-1.264896,38.252102],[-1.264474,38.251771],[-1.263941,38.25157],[-1.263173,38.251292],[-1.262208,38.251156],[-1.260887,38.250862],[-1.25949,38.250188],[-1.258633,38.249869],[-1.25784,38.249997],[-1.257046,38.25012],[-1.256315,38.250001],[-1.255193,38.249597],[-1.251812,38.249051],[-1.24855,38.247925],[-1.247137,38.246886],[-1.24661,38.246477],[-1.24583,38.245947],[-1.245085,38.246472],[-1.244018,38.246984],[-1.243126,38.247155],[-1.242008,38.247499],[-1.240707,38.248277],[-1.238981,38.249287],[-1.238269,38.249416],[-1.238284,38.249448],[-1.238342,38.249561],[-1.2