    SELECT 'matorrales-mediterraneos-y-4090', '4090', 'Matorrales mediterráneos y oromediterráneos primarios y secundarios con dominio frecuente de genisteas', 'Matorral', 'Matorral almohadillado de montaña: matas espinosas y compactas —piornos, erizones, aulagas y aliagas— que crecen pegadas al suelo formando cojines redondeados. Esa forma no es casual, es la respuesta al viento, al frío y al peso de la nieve, y por dentro guarda un microclima donde se refugian otras plantas. Aparece por encima o en el lugar del bosque, en crestas y laderas expuestas.', 0, 38.266556, -1.191209, '#4f7942', '{"type":"Polygon","coordinates":[[[-1.202566,38.269159],[-1.202566,38.269046],[-1.202566,38.268943],[-1.202537,38.26883],[-1.202523,38.268726],[-1.20245,38.268621],[-1.202363,38.268521],[-1.20229,38.268416],[-1.202217,38.268325],[-1.202145,38.268247],[-1.202112,38.268224],[-1.202043,38.268178],[-1.201897,38.268099],[-1.201795,38.268039],[-1.201708,38.267961],[-1.201606,38.267901],[-1.20149,38.2678],[-1.201402,38.267695],[-1.201315,38.267594],[-1.201243,38.267512],[-1.20114,38.267434],[-1.201053,38.267329],[-1.20101,38.267229],[-1.200951,38.267138],[-1.200922,38.267115],[-1.200777,38.267172],[-1.200646,38.267242],[-1.200544,38.267285],[-1.200483,38.267301],[-1.200413,38.267319],[-1.200351,38.267325],[-1.200297,38.267331],[-1.200181,38.267298],[-1.20005,38.267273],[-1.19989,38.267253],[-1.199773,38.267219],[-1.199657,38.267186],[-1.199497,38.267093],[-1.199381,38.26706],[-1.199319,38.267031],[-1.199249,38.266999],[-1.199133,38.266935],[-1.199032,38.266874],[-1.198901,38.266796],[-1.198784,38.266717],[-1.198668,38.266648],[-1.19858,38.266579],[-1.198551,38.266556],[-1.198435,38.266478],[-1.198333,38.266395],[-1.198231,38.266303],[-1.198129,38.266234],[-1.198028,38.266165],[-1.197896,38.266078],[-1.197794,38.265972],[-1.197664,38.26588],[-1.197598,38.26583],[-1.197533,38.265779],[-1.197431,38.265687],[-1.1973,38.265528],[-1.197183,38.265377],[-1.197053,38.265208],[-1.196922,38.265035