    SELECT 'galerias-y-matorrales-92D0', '92D0', 'Galerías y matorrales ribereños termomediterráneos (Nerio-Tamaricetea)', 'Ribera', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 38.243538, -1.202714, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-1.237767,38.248561],[-1.237759,38.248539],[-1.237163,38.247624],[-1.236291,38.246741],[-1.235556,38.245991],[-1.235292,38.245798],[-1.234726,38.245389],[-1.233963,38.244859],[-1.23344,38.244423],[-1.233053,38.243917],[-1.232523,38.24358],[-1.232048,38.243186],[-1.231611,38.242674],[-1.231409,38.242122],[-1.231011,38.241854],[-1.230746,38.241548],[-1.230469,38.240913],[-1.229897,38.240382],[-1.229037,38.239711],[-1.227836,38.238788],[-1.227818,38.238774],[-1.227793,38.238764],[-1.227763,38.238759],[-1.227734,38.238768],[-1.227712,38.238786],[-1.227702,38.238808],[-1.227705,38.238831],[-1.227722,38.238853],[-1.228941,38.239791],[-1.229797,38.240453],[-1.230095,38.240732],[-1.230347,38.240966],[-1.230623,38.241601],[-1.230909,38.241925],[-1.231289,38.242183],[-1.231486,38.242718],[-1.23194,38.243256],[-1.23243,38.24366],[-1.232948,38.243988],[-1.233331,38.244489],[-1.233867,38.244939],[-1.234634,38.245468],[-1.235456,38.246062],[-1.236141,38.246766],[-1.236183,38.246807],[-1.237046,38.247685],[-1.237407,38.248236],[-1.237638,38.248591],[-1.237658,38.248609],[-1.237686,38.248619],[-1.237717,38.248619],[-1.237746,38.248602],[-1.237762,38.248584],[-1.237767,38.248561]]],[[[-1.232936,38.218912],[-1.232908,38.218902],[-1.232863,38.218886],[-1.232808,38.21887],[-1.232741,38.218856],[-1.232651,38.218833],[-1.232502,38.218848],[-1.232123,38.220023],[-1.232111,38.220059],[-1.