    SELECT 'Ceje', 'Helianthemum cinereum', 'flora', 'Mata', 'Crece en tomillares y matorrales sobre suelos secos calizos, dolomíticos o yesosos, hasta 2400 m', 'Perenne sufruticosa, de 4-30 cm, con tallos ascendentes o erectos, redondeados, de tomentosos a glabros. Hojas con limbo de 4-20 x 2-10 mm, pecioladas, de ovadas a oblongo- lanceoladas, opuestas, a veces las superiores alternas, con envés generalmente peloso o tomentoso, las inferiores sin estípulas, las superiores con estípulas foliáceas. Pétalos de 3-6 mm, pequeños, mayores que el cáliz, amarillos. Cápsula de 3-5 mm, ovoide-elipsoidal, glabra o pelosa en el ápice. Semillas pardo-amarillentas. Especie de la que se han considerado cuatro subespecies, tres de ellas endemismos españoles.', NULL, NULL, 'Enero a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_cinereum_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 10 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 4971, 7331381, 10, NULL, NULL, NULL
    UNION ALL
    SELECT 'Artamisa', 'Nepeta nepetella', 'flora', NULL, 'En lugares más secos y pedregosos, preferentemente en sustratos básicos y llega a mayor altitud, casi hasta 3000 m', 'De hojas más estrechas, lanceoladas, cáliz y corola más largos, corola coloreada y de olor intenso.', NULL, NULL, 'Abril a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lamiaceae_-_Nepeta_nepetella.JPG?width=1280', 'Hectonichus (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 10 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Nepeta', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 6554, 7309064, 10, NULL, NULL, NULL
    UNION ALL
    SELECT 'Salado', 'Ononis fruticosa', 'flora', 'Arbusto', 'Pedregales, taludes y matorral sobre suelos calizos y margosos', 'Leguminosa arbustiva de hojas con tres foliolos estrechos y dentados y racimos de flores rosadas con venas más oscuras. Es una planta pionera que fija taludes y pedregales, donde sus raíces profundas aguantan el movimiento del sustrato.', NULL, 'Flores rosadas con venas oscuras bien marcadas; Hojas de tres foliolos estrechos y dentados; Coloniza taludes y pedregales sueltos', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ononis_fruticosa.jpg?width=1280', 'Arrakatanga33 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 10 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 6687, 2977293, 10, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lastón', 'Brachypodium retusum', 'flora', 'Gramínea', 'Pastizales, claros de matorral y ribazos sobre suelos calizos', 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.', NULL, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280', 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 9 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Brachypodium', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 9931, 5676053, 9, NULL, NULL, NULL
    UNION ALL
