    SELECT 'Cebollana', 'Asphodelus cerasifer', 'flora', 'Planta bulbosa', 'Asphodelus cerasiferus vive en pastizales, matorrales y claros de bosque en lugares soleados, sobre todo en sustratos básicos poco desarrollados, hasta 1700 m', 'Tallo de 0,8-2 m, y hojas hasta de 90 x 2,5 cm, con quilla apenas marcada, flores con tépalos hasta de 2,2 cm y estambres algo más cortos; cápsula hasta de 20 mm, esférica.', NULL, NULL, 'Septiembre, noviembre, diciembre, enero, febrero, marzo, abril, mayo, junio, julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/ASPHODELUS_CERASIFERUS_-_BIOSCA_-_IB-825_(Alb%C3%B3).JPG?width=1280', 'Isidre blanc (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 8 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asphodelaceae', 'Asphodelus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 2520, 4931269, 8, NULL, NULL, NULL
