    SELECT 'Cornicabra', 'Pistacia terebinthus', 'flora', 'Arbusto', 'Barrancos, umbrías y matorral alto sobre suelos frescos', 'Arbusto o arbolillo de hoja caduca, con hojas compuestas de foliolos grandes y brillantes y un raquis sin alas, lo que lo separa del lentisco. Suele presentar agallas rojizas y curvadas en forma de cuerno, provocadas por pulgones, que le dan el nombre.', NULL, 'Agallas rojizas curvadas como cuernos en las hojas; Pierde la hoja en invierno, al contrario que el lentisco; Hoja compuesta con foliolo terminal y raquis sin alas', 'Primavera a otoño (pierde la hoja en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistachier2.JPG?width=1280', 'greffer.net (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); PRUG del Parque Regional «Sierra de la Pila», volumen III §2.2 del Plan de Gestión Integral de los relieves y cuencas centro-orientales (Dirección General de Medio Natural, junio de 2018): la norma la enumera en el inventario de especies del propio Parque Regional, que es el ámbito del PRUG y el espacio de esta ficha, con la categoría «De Interés Especial (Catálogo Regional de especies amenazadas de la Región de Murcia)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', NULL, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 7130, 3190580, 4, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zaragatona blanca', 'Plantago albicans', 'flora', 'Hierba', 'Pastizales secos, ribazos y claros de matorral sobre suelos margosos', 'Llantén de aspecto plateado, cubierto de pelos sedosos, con hojas estrechas que salen todas de la base. Levanta espigas cilíndricas y densas en las que las flores se abren de abajo arriba, dejando ver unos estambres largos y colgantes. Resiste bien el pisoteo y la sequía.', NULL, 'Hojas estrechas y plateadas, todas desde la base; Espigas cilíndricas apretadas sobre tallos largos; Estambres largos y colgantes durante la floración', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/633859652/original.jpg', 'Pavel Kúr (CC0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Plantago', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7145, 8424834, 4, NULL, NULL, NULL
    UNION ALL
