    SELECT 'Falguera', 'Asplenium ceterach', 'flora', 'Helecho', 'Crece en grietas o fisuras de roquedos y muros, principalmente en calizas, en lugares no muy fríos y a la sombra, aunque aguanta bien la insolación', 'Helecho perenne, de 5-25 cm, con rizoma cespitoso, corto y superficial, revestido de escamas negras con margen ciliado. Frondes 5-15(25) cm, en roseta, persistentes, de color castaño negruzco en la base, las jóvenes enrolladas en forma de báculo, con láminas lanceoladas, coriáceas, pinnatipartidas, gruesas, onduladas; color verde mate en la parte superior y cubiertas de escamas ferrugíneas o plateadas abajo, con 6-15 pares de pinnas de 8-10 x 4-6 mm, de ápice redondeado y disposición alterna, que se secan en verano. Soros lineares u oblongos, parcialmente cubiertos por las escamas del reverso de las frondes. Esporas color castaño negruzco.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asplenium_ceterach_(Sardinia).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Aspleniaceae', 'Asplenium', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 80438, 2650617, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'astrágalo de Narbona', 'Astragalus alopecuroides', 'flora', NULL, NULL, NULL, NULL, NULL, 'Abril a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Astragalus_alopecuroides.png?width=1280', 'Fturmo (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; PRUG del Parque Regional «Sierra de la Pila», volumen III §2.2 del Plan de Gestión Integral de los relieves y cuencas centro-orientales (Dirección General de Medio Natural, junio de 2018): la norma la enumera en el inventario de especies del propio Parque Regional, que es el ámbito del PRUG y el espacio de esta ficha, que la cita como «Astragalus alopecuroides subsp. grossi» (el backbone de GBIF no reconoce ese nombre y lo resuelve a Astragalus alopecuroides), con la categoría «De Interés Especial (Catálogo Regional de especies amenazadas de la Región de Murcia)»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Astragalus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 2565, 5343178, 3, NULL, NULL, NULL
