    SELECT 'erguen', 'Cytisus lanigerus', 'flora', 'Arbusto', 'Matorral y laderas soleadas sobre suelos secos y pedregosos', 'Arbusto espinoso y muy ramificado que en primavera se cubre por completo de flores amarillas. Sus ramas terminan en espinas fuertes y sus legumbres van cubiertas de pelos sedosos. Forma masas impenetrables que dan refugio a aves de matorral.', NULL, 'Ramas rematadas en espinas rígidas y punzantes; Floración amarilla masiva que cubre toda la mata; Legumbres cubiertas de pelos blancos y sedosos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calycotome_villosa1.jpg?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Cytisus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 2953, 2956364, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Altrobisca', 'Daphne gnidium', 'flora', 'Arbusto', 'Vive en encinares, coscojares, alcornocales y pinares o a veces en formaciones de matorrales, sobre cualquier tipo de sustrato, hasta 1400 m', 'Arbusto 0,5-2 m, ramificado, con tallos muy foliosos. Hojas hasta de 4 cm, lanceoladas 5-10 cm, agudas. Inflorescencias terminales, con flores de unos 6 mm, con un tubo, cuatro pétalos y cuatro estambres que se ven dentro del tubo y otros cuatro que nacen más abajo. Fruto de 7 mm, globoso, carnoso, color rojo, con una semilla.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Daphne_gnidium3.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Thymelaeaceae', 'Daphne', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 3964, 7311306, 3, NULL, NULL, NULL
