    SELECT 'Tomillo blanco', 'Thymus membranaceus', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos secos', 'Tomillo endémico del sureste ibérico, fácil de reconocer por unas brácteas grandes, blancas y membranosas que rodean la inflorescencia y parecen pétalos. Ese conjunto vistoso, más que las flores en sí, es lo que atrae a los insectos.', NULL, 'Brácteas blancas grandes y papiráceas rodeando la flor; Cabezuelas terminales muy vistosas y redondeadas; Aroma intenso a tomillo al frotar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymus_membranaceus_(3).jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 8931, 7306992, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagarto ocelado', 'Timon lepidus', 'fauna', 'Reptil', 'Matorral termomediterráneo semiárido', 'El lagarto más grande de Europa, de hasta 60 cm con la cola incluida. Su dorso es verde con un fino reticulado negro y, en los costados, hileras de ocelos de un azul intenso. Los machos viejos tienen una cabeza enorme y maciza. Es diurno y muy desconfiado.', NULL, 'Ocelos azules alineados en los costados; Dorso verde con retícula negra muy fina; Tamaño grande y cabeza maciza en los machos adultos', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jewelled_Lizard_(Timon_lepidus)_male_found_under_a_stone_by_Jean_NICOLAS_(14166347788).jpg?width=1280', 'Bernard DUPONT from FRANCE (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); PRUG del Parque Regional «Sierra de la Pila», volumen III §2.2 del Plan de Gestión Integral de los relieves y cuencas centro-orientales (Dirección General de Medio Natural, junio de 2018): la norma la enumera en el inventario de especies del propio Parque Regional, que es el ámbito del PRUG y el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Timon', 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2009)', 'VU — Vulnerable (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11582, 2468542, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Espartillo', 'Aphyllanthes monspeliensis', 'flora', 'Hierba', 'Vive en pastos secos y lugares pedregosos en claros de matorral o en lugares abiertos', 'Hierba perenne, hasta de 50 cm, con rizoma muy ramificado y raíces fibrosas. Tallos junciformes, lisos, acanalados, con vainas basales. Flores que nacen en el extremo de los tallos, en general solitarias, rodeadas de una a tres brácteas y cinco bractéolas. Tépalos seis, hasta de 2 cm, de color azulado o violeta. Fruto en cápsula de 3-4 mm, apiculada, con semillas de unos 2 mm.', NULL, NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aphyllanthes_monspeliensis02.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Aphyllanthes', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 2228, 2770868, 2, NULL, NULL, NULL
    UNION ALL
