    SELECT 'Esparraguera de gato', 'Asparagus horridus', 'flora', 'Arbusto', 'Matorrales arborescentes de Juniperus spp.', 'Esparraguera muy espinosa y densa que se enreda entre el matorral y el sabinar litoral, con cladodios rígidos y punzantes.', NULL, 'Cladodios rígidos y punzantes; Se enreda en el matorral; Frutos negros en otoño', 'Otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_stipularis_(detail).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'LC', NULL, 'No incluida en el LESRPE; acompañante de sabinares y matorrales termófilos (HIC 5210)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 33035, 2768695, 2, NULL, NULL, NULL
