    SELECT 'Jarilla', 'Helianthemum hirtum', 'flora', 'Mata', 'Vive en tomillares sobre sustratos calizos, a veces en arenales, hasta 1500 m', 'Planta perenne sufruticosa, con tallos ascendentes, con pelos setosos. Hojas de 3-15 x 1,5-4 mm, lineares o elípticas, opuestas, estipuladas. Sépalos con pelos rígidos; espacios intercostales pubescentes. Pétalos de 6-10 mm, amarillos, a veces blancos. Cápsula de 3-4 mm, muy pelosa.', NULL, NULL, 'Noviembre, marzo, abril, mayo, junio, julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_hirtum.jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 5078, 3595086, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romero Blanco', 'Helianthemum syriacum', 'flora', 'Arbusto', 'Vive en matorrales sobre calizas o margas, hasta 1200 m', 'Pequeño arbusto de 5-50 cm, con hojas de 10-50 x 2-8 mm, opuestas, estipuladas, ± lineares, con margen revuelto, blanquecinotomentosas en el envés. Flores en cimas unilaterales multifloras; pétalos de 5-10 mm, amarillos. Cápsula de 3-4 mm, pelosa arriba.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_syriacum_(habitus).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 5101, 3595430, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla', 'Helianthemum violaceum', 'flora', 'Mata', 'Tomillares y matorral raso sobre suelos calizos y margosos secos', 'Jarilla pequeña de hojas estrechas y grisáceas con el borde enrollado, que se cubre en primavera de flores amarillas efímeras. Como en todas las jarillas, los pétalos apenas duran una mañana y se renuevan cada día.', NULL, 'Hojas estrechas con el borde enrollado hacia abajo; Flores amarillas que duran solo unas horas; Mata baja y grisácea del tomillar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_violaceum_habitus_SierraMadrona.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, NULL, 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'EN — En peligro (Lista Roja española, 2010)', 'UICN España: EN (En peligro) (2010)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 5102, 8148601, 2, NULL, NULL, NULL
