    SELECT 'Klasea flavescens', 'Klasea flavescens', 'flora', 'Hierba', 'Pastizales secos, claros de matorral y taludes sobre suelos margosos', 'Compuesta de hojas divididas y algo espinosas, con capítulos grandes de flores amarillas rodeados de brácteas secas y brillantes. A distancia recuerda a un cardo, pero sus hojas pinchan mucho menos.', NULL, 'Capítulos amarillos grandes y solitarios; Brácteas secas y algo brillantes bajo la flor; Hojas divididas, con dientes poco punzantes', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Klasea_flavescens0001_01.jpg?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Klasea', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 5535, 3091206, 2, NULL, NULL, NULL
