    SELECT 'Castañuela', 'Asteriscus spinosus', 'flora', NULL, NULL, NULL, NULL, NULL, 'Octubre, noviembre, diciembre, febrero, marzo, abril, mayo, junio, julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pallenis_spinosa_3.JPG?width=1280', 'User:Xemenendura (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Asteriscus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', 'Fichada hasta el 2026-08-17 como «Pallenis spinosa», que EIDOS da por sinónimo. taxonid 80443: «Pallenis spinosa (L.) Cass.» es Sinónimo y «Asteriscus spinosus (L.) Schulz Bip.» Aceptado/válido. Se adopta el nombre aceptado; la gbifSpeciesKey NO cambia porque el backbone de GBIF acepta el nombre anterior y es esa key la que lleva las ocurrencias.', 80443, 5385215, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Hierba de la sangre fina', 'Paronychia suffruticosa', 'flora', NULL, 'Paronychia suffruticosa vive en matorrales secos, preferentemente calcícolas, hasta 1800 m', 'Subarbustiva, de color violáceo, con raíz leñosa; tallos erectos de 10-40 cm; brácteas muy cortas, que no recubren las flores, estas dispuestas en glomérulos pequeños, terminales y laterales, muy numerosos y separados; flores de 1,7-2,2 mm, con sépalos cuculados, coriáceos, cortamente aristados.', NULL, NULL, 'Todo el año', 'https://bs.plantnet.org/image/o/ba404fcf16ff8c29e139d41308827c139c69f20e', 'González Hernández Antonio (CC BY-SA 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Paronychia', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 6774, 5529030, 2, NULL, NULL, NULL
