    SELECT 'Sedo de hojas gruesas', 'Sedum dasyphyllum', 'flora', 'Planta suculenta', 'Prados calcáreos del Alysso-Sedion albi', 'Crasulácea diminuta de hojas gruesas, casi esféricas y de un gris azulado, dispuestas de dos en dos y cubiertas de pelillos glandulosos que la hacen pegajosa. Forma almohadillas en grietas y muros y da flores blancas con venas rosadas.', NULL, 'Hojas casi esféricas, opuestas y de gris azulado; Tacto pegajoso por los pelillos glandulosos; Flores blancas con finas venas rosadas', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_dasyphyllum_(1)_6.jpg?width=1280', 'Ghislain118 http://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Sedum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 8203, 7172720, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Salamanquesa común', 'Tarentola mauritanica', 'fauna', 'Reptil', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Gecko robusto de piel tuberculada, activo al anochecer sobre roquedos, muros y cortados, donde caza insectos atraídos por la luz.', NULL, 'Piel rugosa con tubérculos; Activa al atardecer; Trepa por rocas y muros', 'Todo el año', 'https://inaturalist-open-data.s3.amazonaws.com/photos/605672084/original.jpg', 'jrodben (CC BY-NC 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Phyllodactylidae', 'Tarentola', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11692, 2445034, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zamarrilla', 'Teucrium capitatum', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelo calizo pedregoso', 'Mata pequeña y grisácea, de hojas estrechas con el borde enrollado, que remata sus tallos en cabezuelas apretadas de flores blancas o crema. Es una de las plantas más constantes del tomillar y una fuente de néctar importante en pleno verano.', NULL, 'Cabezuelas redondas y compactas al final del tallo; Aspecto general blanquecino o grisáceo; Flores sin labio superior, típicas del género', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_capitatum2006.jpg?width=1280', 'No machine-readable author provided. Víctor M. Vicente Selvas~commo… (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 8784, 7308670, 2, NULL, NULL, NULL
    UNION ALL
