    SELECT 'achicoria falsa', 'Cheirolophus intybaceus', 'flora', 'Mata', 'Habita sobre acantilados y laderas de naturaleza margo-arenosa muy deleznables junto a la línea de costa, en el piso termomediterráneo de ombroclima seco', 'Planta procumbente y multicaule, de base sufruticosa y hojas subcrasas, las inferiores liradopinnatipartidas y las superiores linear-lanceoladas. Tallos floríferos estriado-glandulosos, subáfilos y engrosados por debajo del capítulo. Brácteas del involucro oblongas, con apéndice semilunar y con 9-11 cilios. Aquenios de 4x2 mm, negruzcos, glabrescentes y con vilano de hasta 3 mm de longitud.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheirolophus_intybaceus_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Cheirolophus', 'No evaluada en la Lista Roja mundial de la UICN', 'CR — En peligro crítico (Lista Roja española, 2010)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 3544, 3097063, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cabrilla', 'Cytinus ruber', 'flora', 'Planta parásita', 'Sobre las raíces de jaras y jarillas, en matorral mediterráneo', 'Planta parásita sin clorofila que vive dentro de las raíces de las jaras y solo asoma para florecer: un ramillete de flores rosadas y blancas que brota directamente del suelo, al pie de la mata hospedadora. El resto del año es invisible.', NULL, 'Brota directamente del suelo, sin tallo ni hojas verdes; Siempre al pie de una jara o jarilla; Flores rosadas con brácteas carnosas y llamativas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cytinus_ruber_(flowering_plants).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); PRUG del Parque Regional «Sierra de la Pila», volumen III §2.2 del Plan de Gestión Integral de los relieves y cuencas centro-orientales (Dirección General de Medio Natural, junio de 2018): la norma la enumera en el inventario de especies del propio Parque Regional, que es el ámbito del PRUG y el espacio de esta ficha, con la categoría «De Interés Especial (Catálogo Regional de especies amenazadas de la Región de Murcia)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cytinaceae', 'Cytinus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 3809, 3941138, 1, NULL, NULL, NULL
