    SELECT 'Rabo de gato', 'Sideritis leucantha', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos y margosos', 'Rabogato de tallos erguidos cubiertos de pelusa blanca, con flores de color blanco crema dispuestas en verticilos separados a lo largo de la espiga. Es un endemismo del sureste ibérico y una de las plantas usadas tradicionalmente en infusión.', NULL, 'Flores blanco crema en anillos separados por el tallo; Toda la planta blanquecina y algo lanuda; Brácteas anchas y punzantes bajo cada grupo de flores', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alb-S.leucantha-13.jpg?width=1280', 'Philmarin (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2014)', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 8340, 7307627, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerraja fina', 'Sonchus tenerrimus', 'flora', 'Hierba', 'Muros, taludes, cunetas y pies de roca en ambientes secos y alterados', 'Cerraja de hojas muy divididas en segmentos estrechos, casi filiformes, que la distinguen de sus parientes de hoja ancha. Brota en cualquier grieta o talud, suelta látex blanco al partirla y florece prácticamente todo el año en clima cálido.', NULL, 'Hojas partidas en segmentos muy estrechos y separados; Látex blanco abundante al romper el tallo; Capítulos amarillo pálido y vilanos sedosos y blancos', 'Casi todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sonchus_tenerrimus_01.JPG?width=1280', 'Luca Fornasari (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Sonchus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 9686, 3105768, 1, NULL, NULL, NULL
    UNION ALL
