    SELECT 'Alcaudón real', 'Lanius meridionalis', 'fauna', 'Ave', 'Campo abierto con matorral disperso, cables y posaderos altos', 'Alcaudón grande, gris por encima y con un antifaz negro que le cruza el ojo. Caza al acecho desde un posadero alto y tiene la costumbre de empalar sus presas —insectos, lagartijas, ratones— en espinas y alambres, formando pequeñas despensas.', NULL, 'Antifaz negro sobre fondo gris claro; Siempre en lo alto de un cable, poste o mata; Presas empaladas en espinos cerca de su territorio', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdlicher-Raubw%C3%BCrger_2018-01-07_0003.jpg?width=1280', 'Andreas Trepte (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; PRUG del Parque Regional «Sierra de la Pila», volumen III §2.2 del Plan de Gestión Integral de los relieves y cuencas centro-orientales (Dirección General de Medio Natural, junio de 2018): la norma la enumera en el inventario de especies del propio Parque Regional, que es el ámbito del PRUG y el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal; ave del apartado de la ZEPA ES0000174 (Sierra de la Pila)', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'VU — Vulnerable (Lista Roja mundial de la UICN, 2017)', 'NT — Casi amenazada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011); UICN España: NT (Casi amenazado) (2004)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 16426, 7341500, 3, 'ES0000174', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000174","name":"Sierra de la Pila","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000174 (Sierra de la Pila), sección 3.2"}'
